.libPaths(c(file.path(Sys.getenv("W"), "lib"), .libPaths())); library(zujson)
t <- function(label, expr) {
  r <- tryCatch(expr, condition = function(e) paste0("<", paste(class(e), collapse="/"), "> ", conditionMessage(e)))
  cat(sprintf("%-34s %s\n", label, if (is.character(r) && length(r)==1 && startsWith(r,"<")) r else paste(deparse(r, control=c("keepNA","keepInteger","niceNames","showAttributes")), collapse="")))
}
p <- json_parse
# doc table rows
for (j in c('{"a": 1}','[1, 2, 3]','[1, 2.5]','[true, false]','["a", "b"]','[1, "a"]','[1, {}]','[]','[null, null]','null','[true, 1]','[true,1.5]','[null,1]','[null,"a"]','[null,true]','[1,null,2.5]','[true,"a"]','[[1,2],[3,4]]','[[]]','{}','[{}]','[null,{}]','[null,[1]]','1','1.0','1e2','-0','-0.0','2147483647','2147483648','-2147483647','-2147483648','[1,2147483648]','[-2147483648]','[1,-2147483648]','9007199254740993','18446744073709551615','18446744073709551616','-9223372036854775808','-9223372036854775809','1e309','-1e309','[1e309,1]','1e-400','123456789012345678901234567890','0.1','"a"','""','true','[1E400]','1.5e400','[1,1e400,"a"]','')) t(j, p(j))
cat("--- coerce\n")
for (j in c('[1, "a"]','[1.5,"a"]','[true,"a"]','[null,"a",1]','[1,2.5,true,"x"]','[1e5,"a"]','[100000,"a"]','[1e15,"a"]','[1e16,"a"]','[123456.789012345,"a"]','[0.1,"a"]','[1e-5,"a"]','[1e309,"a"]','[2147483648,"a"]','[1e22,"a"]','[1e21,"a"]','[0.30000000000000004,"a"]','[1.0,"a"]','[-0.0,"a"]','[1,{}]','[1,[2],"a"]','[1,"a",null]','[100000.5,"x"]','[12345678901234567890,"a"]','[3.14159265358979,"a"]','[1e-300,"a"]','[true,null]','[1.10,"a"]','[9007199254740993,"a"]','[123456789012,"a"]', '[1E5,"a"]')) { t(j, p(j, simplify="coerce")); }
cat("--- none\n")
for (j in c('[1,2]','[]','{"a":[1,[2]]}','[null]','1')) t(j, p(j, simplify=FALSE))
t("none == 'none'", identical(p('[1,[2,null],{"a":[]}]', simplify=FALSE), p('[1,[2,null],{"a":[]}]', simplify="none")))
t("TRUE == preserve", identical(p('[1,[2,null],{"a":[1,"b"]}]', simplify=TRUE), p('[1,[2,null],{"a":[1,"b"]}]', simplify="preserve")))
cat("--- args\n")
t("simplify NA", p("1", simplify=NA)); t("simplify 1", p("1", simplify=1)); t("simplify 'x'", p("1", simplify="x")); t("simplify c", p("1", simplify=c("none","coerce"))); t("simplify NULL", p("1", simplify=NULL)); t("simplify NA_chr", p("1", simplify=NA_character_)); t("simplify 'pres'", p("1", simplify="pres")); t("simplify factor", p("[1]", simplify=factor("none")))
t("simplify named", p("[1,2]", simplify=c(a="none")))
t("df NA", p("1", data_frame=NA)); t("df 1", p("1", data_frame=1)); t("df 'TRUE'", p("1", data_frame="TRUE"))
t("x NULL", p(NULL)); t("x NA", p(NA)); t("x NA_chr", p(NA_character_)); t("x chr2", p(c("1","2"))); t("x chr0", p(character())); t("x num", p(1)); t("x list", p(list("1"))); t("x factor", p(factor("1"))); t("x empty", p("")); t("x raw0", p(raw())); t("x ws", p("  ")); t("x missing", p())
t("x classed chr", p(structure("[1]", class="json")))
t("x named chr", p(c(a="[1]")))
t("raw x str", json_parse_raw("1")); t("raw x NULL", json_parse_raw(NULL))
t("file NA", json_parse_file(NA_character_)); t("file 2", json_parse_file(c("a","b"))); t("file missing", json_parse_file("/nonexistent/x.json")); t("file dir", json_parse_file(tempdir())); t("file ''", json_parse_file("")); t("file num", json_parse_file(1))
t("validate NA", json_validate(NA_character_)); t("validate NULL", json_validate(NULL)); t("validate 2", json_validate(c("1","2"))); t("validate ''", json_validate("")); t("validate raw0", json_validate(raw())); t("validate num", json_validate(1)); t("validate lgl NA", json_validate(NA)); t("validate 1e309", json_validate("1e309")); t("validate NaN", json_validate("NaN")); t("validate nul", json_validate('"\\u0000"'))
t("parse nul", p('"\\u0000"')); t("parse nul key", p('{"a\\u0000":1}'))
t("ndjson NA", json_parse_ndjson(NA_character_)); t("ndjson ''", json_parse_ndjson("")); t("ndjson raw0", json_parse_ndjson(raw())); t("ndjson chr2", json_parse_ndjson(c("1","2"))); t("ndjson NULL", json_parse_ndjson(NULL))
cat("--- strings\n")
t("trailing", p("1 2")); t("trailing comma", p("[1,]")); t("comment", p("[1] // x")); t("BOM", p("﻿[1]")); t("BOM raw", p(as.raw(c(0xef,0xbb,0xbf,0x31)))); t("2 BOM", p("﻿﻿[1]"));  t("BOM only", p("﻿"))
t("NaN", p("NaN")); t("Infinity", p("[Infinity]")); t("-Infinity", p("-Infinity")); t("nan", p("nan")); t("0x10", p("0x10")); t("+1", p("+1")); t("01", p("01")); t(".5", p(".5")); t("1.", p("1.")); t("single quote", p("'a'"))
r <- p('"caf\\u00e9 \\ud83d\\ude00"'); t("escapes", r); t("enc", Encoding(r))
t("lone surrogate", p('"\\ud83d"'))
l1 <- iconv('["café"]', "UTF-8", "latin1"); t("latin1 str input", p(l1)); t("latin1 validate", json_validate(l1)); t("latin1 raw input", p(charToRaw(l1)))
t("latin1 ndjson", json_parse_ndjson(l1))
by <- '["a"]'; Encoding(by) <- "bytes"; t("bytes input", p(by)); t("bytes validate", json_validate(by)); t("bytes ndjson", json_parse_ndjson(by))
t("embedded nul raw", p(as.raw(c(0x31,0x00)))); t("raw nul mid", p(c(charToRaw('["a'), as.raw(0), charToRaw('"]'))))
t("dup keys", p('{"a":1,"a":2}')); t("empty key", p('{"":1}')); t("names dup", names(p('{"a":1,"a":2,"":3}')))
t("NA key", p('{"NA":1}')); t("key enc", Encoding(names(p('{"é":1}'))))
t("string 'NA'", p('["NA", null]'))
t("is.na of 'NA' string", is.na(p('["NA", null]')))
